class Solution { public String shortestSuperstring(String[] w) { int n=w.length,N=1<<n;int[][]o=new int[n][n];for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(i!=j)for(int k=Math.min(w[i].length(),w[j].length());k>0;k--)if(w[i].endsWith(w[j].substring(0,k))){o[i][j]=k;break;}String[][]d=new String[N][n];for(int i=0;i<n;i++)d[1<<i][i]=w[i];for(int m=1;m<N;m++)for(int i=0;i<n;i++)if(d[m][i]!=null)for(int j=0;j<n;j++)if((m&(1<<j))==0){int z=m|1<<j;String c=d[m][i]+w[j].substring(o[i][j]);if(d[z][j]==null||c.length()<d[z][j].length()||(c.length()==d[z][j].length()&&c.compareTo(d[z][j])<0))d[z][j]=c;}String b=null;for(String s:d[N-1])if(s!=null&&(b==null||s.length()<b.length()||(s.length()==b.length()&&s.compareTo(b)<0)))b=s;return b;} }
